def apply_event(state, event):
    key = event['id']
    new_state = {k: dict(v) for k, v in state.items()}
    current = state.get(key)
    if current is not None:
        if event['version'] <= current['version']:
            return new_state
    new_state[key] = {'version': event['version'], 'value': event['value']}
    return new_state
